// ================= 小云雀音效（2026-11-05）：宝箱 10 款 + 领悟技能 10 款 =================
// 宝箱：开箱按箱子里的东西分档放不同的声音（作者 11-05：原来的宝光音效不太行）——
//   普通箱 → 06 轻快木箱；精良箱（大还丹 / 装备 / 玉）→ 01 木箱金光；灵石多（≥100）→ 03 金币珠宝；稀有箱（灵石≥200、复活类、三样以上）→ 05 金光冲天；
//   锁灵阵破阵成功 → 07 神器钟鸣仙乐。开箱时原来的随机「宝光」音效让掉，不叠在一起。
// 领悟技能 10 款：先只放进测试面板「声音测试」里试听，等作者挑好再接进游戏。
(function () {
  const D = {"chest": ["data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,"], "skill": ["data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,", "data:audio/mpeg;base64,"]};
  const CN = ["木箱弹开 + 金光闪烁（精良箱）", "石匣推开 + 灵力嗡鸣", "金属锁扣 + 金币珠宝（灵石多的箱子）", "玉匣玉鸣 + 仙气风铃", "稀有：锁链崩开 + 金光冲天（稀有箱）", "普通小木箱 · 轻快（普通箱）", "神器：机关解锁 + 钟鸣仙乐（锁灵阵破阵）", "灵石晶莹 + 水晶回响", "锦盒 + 古筝上行", "秘境：符咒碎裂 + 紫金法光"], SN = ["灵光降体 + 悠远钟鸣", "灵气漩涡收拢 + 剑鸣", "古卷展开 + 顿悟音", "风铃编钟层层上行", "灵力脉动 → 突破音", "剑意觉醒 · 清越长剑鸣", "古琴一拨 + 晶莹仙音", "古钟仙乐 · 玄妙庄重", "学会新技能 · 轻快短促", "星辰灌顶 · 史诗"];
  window.XYQ_SFX = D;
  try {
    const L = window.VOICE_LAB || (window.VOICE_LAB = []);
    D.chest.forEach((src, i) => L.push({ group: '宝箱音效 · 小云雀 10 款（已按档位接入开箱）', name: String(i + 1).padStart(2, '0'), desc: CN[i], src }));
    D.skill.forEach((src, i) => L.push({ group: '领悟技能音效 · 小云雀 10 款（待挑选）', name: String(i + 1).padStart(2, '0'), desc: SN[i], src }));
  } catch (e) {}
  const BUF = {};
  function play(kind, i, vol = .85) {
    try {
      if (typeof AUD !== 'undefined' && AUD.muted) return;
      const src = D[kind][i]; if (!src) return;
      if (typeof AC !== 'undefined' && AC && typeof AUD !== 'undefined' && AUD.mode === 'webaudio' && AUD.sfxGain) {
        const k = kind + i, go = b => { const s = AC.createBufferSource(); s.buffer = b; const g = AC.createGain(); g.gain.value = vol; s.connect(g); g.connect(AUD.sfxGain); s.start(); };
        if (BUF[k]) return go(BUF[k]);
        fetch(src).then(r => r.arrayBuffer()).then(b => AC.decodeAudioData(b)).then(b => { BUF[k] = b; go(b); }).catch(() => { const a = new Audio(src); a.volume = vol; a.play().catch(() => {}); });
      } else { const a = new Audio(src); a.volume = vol; a.play().catch(() => {}); }
    } catch (e) {}
  }
  window.playXyqSfx = play;
  // 开箱分档
  function tierOf(lines) {
    const txt = (lines || []).map(String).join('|'); let gold = 0; const m = txt.match(/灵石\s*×\s*(\d+)/); if (m) gold = +m[1];
    const n = (lines || []).length;
    if (gold >= 200 || /复活|还魂|回魂|神器|仙衣/.test(txt) || n >= 3) return 4;   // 05 稀有
    if (/大还丹|甲|剑|袍|靴|玉|符|丹.*×\s*[2-9]/.test(txt)) return 0;            // 01 精良
    if (gold >= 100) return 2;                                                     // 03 灵石多
    return 5;                                                                      // 06 普通
  }
  if (typeof showPanel === 'function') showPanel = (o => function (title, lines) {
    if (String(title || '') === '打开宝箱') {
      try { const now = performance.now(); if (typeof AUD !== 'undefined') for (const b of ['jingle_bx1', 'jingle_bx2', 'jingle_bx5', 'jingle_levelup']) AUD.lastPlay[b] = now + 1000; } catch (e) {}   // 让掉原来的宝光音效
      play('chest', tierOf(lines));
    }
    return o.apply(this, arguments);
  })(showPanel);
  // 锁灵阵破阵成功
  if (typeof window.breakSeal === 'function') window.breakSeal = (o => function () { const p = o.apply(this, arguments); try { Promise.resolve(p).then(ok => { if (ok === true) play('chest', 6, .95); }); } catch (e) {} return p; })(window.breakSeal);
})();
